/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: active, track
 *   Constants: trackId, videoKey, previewKey, enabled
 * Tests
 *   - preview keys are bound to their track and live outside every audio and video classifier
 *   - the public gate needs the flag, an explicit Video, a complete preview, and the exact active source
 *   - a gate failure, revision mismatch, or revalidation never reaches storage
 *   - reconciliation classifies orphaned, missing, incomplete, stale, invalid, and duplicate preview evidence
 * @end-catalog */

import assert from 'node:assert/strict';
import test from 'node:test';

import { resolveMotionPreview } from '../../src/controllers/motionPreviewController';
import { reconcileMotionPreviewStorage } from '../../src/services/media/motionPreviewReconciliation';
import { isMotionPreviewRevision, publicMotionPreviewForTrack } from '../../src/services/media/motionPreviewService';
import {
    createMotionPreviewObjectKey,
    isMotionPreviewCandidateKey,
    isMotionPreviewObjectKeyForTrack,
    motionPreviewLifecycleKeys
} from '../../src/utils/motionPreviewStorageKey';
import { isAudioStorageCandidateKey, isVideoStorageCandidateKey } from '../../src/services/audio/audioReconciliationService';

const trackId = '64b000000000000000000001';
const videoKey = `video/${trackId}/64b0000000000000000000aa`;
const previewKey = `motion-preview/${trackId}/64b0000000000000000000ee`;
const enabled = { FINITUDE_MOTION_PREVIEWS_ENABLED: 'true' } as NodeJS.ProcessEnv;

const active = (overrides: Record<string, unknown> = {}) => ({
    status: 'ready', revision: `pv_${'1'.repeat(32)}`, s3Key: previewKey, versionId: 'v1', etag: '"etag-1"',
    byteLength: 900_000, contentType: 'video/mp4', durationMs: 6000, width: 854, height: 480,
    sha256: 'a'.repeat(64), source: { s3Key: videoKey }, createdBy: 'admin', updatedAt: new Date(), ...overrides
});

const track = (overrides: Record<string, unknown> = {}, previewOverrides: Record<string, unknown> = {}) => ({
    _id: trackId, uploadStatus: 'ready', mediaType: 'video', s3Key: videoKey, contentType: 'video/mp4',
    publicationStatus: 'ready', visibility: 'public',
    motionPreview: { active: active(previewOverrides), pending: null, cleanup: null, revision: 3 },
    ...overrides
});

test('preview keys are bound to their track and live outside every audio and video classifier', () => {
    const created = createMotionPreviewObjectKey(trackId.toUpperCase());
    assert.equal(isMotionPreviewObjectKeyForTrack(created, trackId), true);
    assert.equal(isMotionPreviewObjectKeyForTrack(created, '64b000000000000000000002'), false);
    assert.equal(isMotionPreviewObjectKeyForTrack(`video/${trackId}/64b0000000000000000000ee`, trackId), false);
    assert.equal(isMotionPreviewCandidateKey(previewKey), true);
    assert.equal(isAudioStorageCandidateKey(previewKey), false);
    assert.equal(isVideoStorageCandidateKey(previewKey), false);
    assert.deepEqual(motionPreviewLifecycleKeys({
        active: active() as any, cleanup: null, revision: 1,
        pending: { status: 'failed', s3Key: `motion-preview/${trackId}/64b0000000000000000000ff`, versionId: null } as any
    }, trackId), [
        { key: previewKey, versionId: 'v1' },
        { key: `motion-preview/${trackId}/64b0000000000000000000ff`, versionId: null }
    ]);
    assert.throws(() => motionPreviewLifecycleKeys({ active: active({ s3Key: videoKey }) as any, pending: null, cleanup: null, revision: 1 }, trackId));
});

test('the public gate needs the flag, an explicit Video, a complete preview, and the exact active source', () => {
    assert.equal(isMotionPreviewRevision(`pv_${'a'.repeat(32)}`), true);
    assert.equal(isMotionPreviewRevision('pv_short'), false);
    assert.equal(publicMotionPreviewForTrack(track(), enabled)?.s3Key, previewKey);
    assert.equal(publicMotionPreviewForTrack(track(), {} as NodeJS.ProcessEnv), null);
    for (const hidden of [
        track({ mediaType: 'audio', s3Key: `audio/${trackId}/64b0000000000000000000aa` }),
        track({ s3Key: `video/${trackId}/64b0000000000000000000bb` }),
        track({}, { status: 'pending' }),
        track({}, { etag: 'weak' }),
        track({}, { byteLength: 5 * 1024 * 1024 }),
        track({}, { revision: 'pv_bad' }),
        track({}, { s3Key: `motion-preview/64b000000000000000000002/64b0000000000000000000ee` }),
        track({ motionPreview: null })
    ]) {
        assert.equal(publicMotionPreviewForTrack(hidden, enabled), null);
    }
});

test('a gate failure, revision mismatch, or revalidation never reaches storage', async () => {
    const previous = process.env.FINITUDE_MOTION_PREVIEWS_ENABLED;
    process.env.FINITUDE_MOTION_PREVIEWS_ENABLED = 'true';
    try {
        let heads = 0;
        const headObject = async () => { heads += 1; return { ContentLength: 900_000, ETag: '"etag-1"', VersionId: 'v1' }; };
        const signal = new AbortController().signal;
        const resolve = (candidate: any, revision?: string, ifNoneMatch?: string) => resolveMotionPreview(
            trackId, revision, signal, ifNoneMatch, { findReadyTrack: async () => candidate, headObject }
        );

        assert.equal((await resolve(null)).status, 'notFound');
        assert.equal((await resolve(track({ visibility: 'hidden' }))).status, 'notFound');
        assert.equal((await resolve(track({ s3Key: `video/${trackId}/64b0000000000000000000bb` }))).status, 'notFound');
        assert.equal((await resolve(track(), `pv_${'2'.repeat(32)}`)).status, 'notFound');
        assert.equal((await resolve(track(), undefined, '"etag-1"')).status, 'notModified');
        assert.equal(heads, 0);

        const ready = await resolve(track(), `pv_${'1'.repeat(32)}`);
        assert.equal(ready.status, 'ready');
        assert.equal(heads, 1);
        if (ready.status === 'ready') {
            assert.deepEqual(ready.params, {
                Bucket: process.env.S3_BUCKET_NAME, Key: previewKey, IfMatch: '"etag-1"', VersionId: 'v1'
            });
            assert.equal(await ready.authorize(), true);
        }

        // Storage metadata that disagrees with the record, or a replacement during HEAD, is not served.
        const mismatched = await resolveMotionPreview(trackId, undefined, signal, undefined, {
            findReadyTrack: async () => track(), headObject: async () => ({ ContentLength: 1, ETag: '"etag-1"', VersionId: 'v1' })
        });
        assert.equal(mismatched.status, 'notFound');
        let reads = 0;
        const replaced = await resolveMotionPreview(trackId, undefined, signal, undefined, {
            findReadyTrack: async () => (++reads === 1 ? track() : track({}, { revision: `pv_${'3'.repeat(32)}` })),
            headObject
        });
        assert.equal(replaced.status, 'notFound');
    } finally {
        if (previous === undefined) delete process.env.FINITUDE_MOTION_PREVIEWS_ENABLED;
        else process.env.FINITUDE_MOTION_PREVIEWS_ENABLED = previous;
    }
});

test('reconciliation classifies orphaned, missing, incomplete, stale, invalid, and duplicate preview evidence', () => {
    const orphanKey = `motion-preview/${trackId}/64b0000000000000000000ab`;
    const missingTrack = { ...track(), _id: '64b000000000000000000002', s3Key: `video/64b000000000000000000002/64b0000000000000000000aa`,
        motionPreview: { active: active({ s3Key: `motion-preview/64b000000000000000000002/64b0000000000000000000cd`, source: { s3Key: `video/64b000000000000000000002/64b0000000000000000000aa` } }), pending: null, cleanup: null, revision: 1 } };
    const staleTrack = { ...track(), _id: '64b000000000000000000003', s3Key: `video/64b000000000000000000003/64b0000000000000000000aa`,
        motionPreview: { active: active({ s3Key: `motion-preview/64b000000000000000000003/64b0000000000000000000cd` }), pending: { status: 'failed', s3Key: `motion-preview/64b000000000000000000003/64b0000000000000000000ce`, outcomeUnknown: true }, cleanup: null, revision: 1 } };
    const invalidTrack = { ...track(), _id: '64b000000000000000000004', motionPreview: { active: active(), pending: null, cleanup: null, revision: 1 } };
    const report = reconcileMotionPreviewStorage([track(), missingTrack, staleTrack, invalidTrack], [
        { key: previewKey, size: 1 },
        { key: orphanKey, size: 1 },
        { key: `motion-preview/64b000000000000000000003/64b0000000000000000000cd`, size: 1 },
        { key: 'motion-preview/not-a-key', size: 1 }
    ]);

    assert.deepEqual(report.orphanedObjects.map((object) => object.key), [orphanKey, 'motion-preview/not-a-key']);
    assert.deepEqual(report.missingObjects.map((reference) => reference.audioTrackId), ['64b000000000000000000002']);
    assert.deepEqual(report.incompleteTracks.map((entry) => entry.audioTrackId), ['64b000000000000000000003']);
    // Track 4 also holds another track's Video key, so its preview is stale as well as invalid.
    assert.deepEqual(report.staleTracks.map((entry) => entry.audioTrackId), ['64b000000000000000000003', '64b000000000000000000004']);
    assert.deepEqual(report.invalidStorageKeys.map((reference) => reference.audioTrackId), ['64b000000000000000000004']);
    assert.deepEqual(report.invalidStorageObjects.map((object) => object.key), ['motion-preview/not-a-key']);
    assert.equal(report.summary.databasePreviewTrackCount, 4);
});
